package com.courier.common.dto;

import com.courier.common.enums.Channel;
import com.courier.common.enums.Priority;
import lombok.*;

import java.util.Map;
import java.util.UUID;

/*
 * This is the INTERNAL Kafka contract between courier-api and courier-worker.
 * It is never sent to or received from external clients.
 *
 * Key differences from NotificationRequest:
 * - eventId: generated by courier-api for deduplication at consumer side.
 *   Different from correlationId (client's key) - this is our internal key.
 * - notificationId: the DB primary key, so the worker can update the right row.
 * - timestamp: when the event was created, for auditing.
 * - sourceService: which service published this event, for tracing.
 *
 * This class must be serializable to JSON by Jackson (no-arg constructor needed,
 * which @NoArgsConstructor provides). Kafka's JsonSerializer uses Jackson.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class NotificationEvent {

    private String eventId;           // UUID as String - for Redis SETNX dedup key
    private UUID notificationId;      // DB primary key - worker updates this row
    private String correlationId;     // from request - for log tracing
    private Channel channel;
    private String recipient;
    private String subject;
    private String content;
    private Priority priority;
    private Map<String, String> metadata;
    private long timestamp;           // epoch millis - when event was created
    private String sourceService;     // "courier-api" - for distributed tracing
}